def design(x, k, m):
    from itertools import combinations_with_replacement
    t = np.tanh(x * k)
    cols = [np.ones(len(x)), *x.T, *t.T]
    if 'q' in m:
        cols.extend((x[:, i] * x[:, j] for (i, j) in combinations_with_replacement(range(4), 2)))
    if 'd' in m:
        cols.extend((x * x).T)
    if 'p' in m:
        cols.extend((x[:, i] * x[:, j] for (i, j) in [(0, 2), (1, 3)]))
    if 's' in m:
        cols.extend(np.sin(2 * x).T)
    if 'f' in m:
        cols.extend((x / (1 + x * x)).T)
    return np.column_stack(cols)

def pred(p, x, j, m):
    a = x[:, j]
    h = p[2] + p[3] * a
    lin = p[0] + x @ p[4:8]
    if m in ('mix', 'mix_no_lin', 'mix_same'):
        h = h + x @ p[8:12]
    if m == 'mix_no_lin':
        lin = p[0]
    if m == 'mix_same':
        lin = p[0] + p[4] * h
    if m == 'rational':
        return lin + p[1] * h / np.sqrt(1 + h * h)
    if m == 'frac':
        return lin + p[1] * h / (1 + h * h)
    if m == 'poly5':
        return lin + sum((p[8 + k] * a ** (k + 2) for k in range(4)))
    if m == 'affine':
        return lin
    return lin + p[1] * np.tanh(h)

def cd(a, b, k, m):
    t = [b]
    if 'c' in m:
        t.append(1 - np.cos(k[0] * b))
    if 'r' in m:
        t.append(b * b / (1 + k[0] * b * b))
    if 's' in m:
        t.append(np.sin(k[1] * b))
    if 'q' in m:
        t.append(b * b)
    if '3' in m:
        t.append(b ** 3)
    if 'u' in m:
        t.append(b / (1 + k[1] * b * b))
    if 'i' in m:
        t.extend([a * b, np.tanh(a) * b, a * (1 - np.cos(2 * b)), b * (1 - np.cos(2 * a))])
    if 'v' in m:
        t.extend([np.sin(2 * (a + b)) - np.sin(2 * a) - np.sin(2 * b), np.cos(2 * (a + b)) - np.cos(2 * a) - np.cos(2 * b) + 1])
    return np.stack(t, axis=-1)

def features(a, k, m):
    t = k[0] * a
    if m == 'arg3':
        t = t + k[2] * a ** 3
    if m == 'argsin':
        t = t + k[2] * np.sin(k[3] * a)
    if m == 'argrat':
        t = t + k[2] * a / (1 + k[3] * a * a)
    d = np.tanh(t) + k[1] * a
    if m == 'sin':
        d += k[2] * np.sin(k[3] * a)
    if m == 'sin3':
        d += k[2] * np.sin(k[3] * a) + k[4] * a ** 3
    if m == 'cos_even':
        d += k[2] * (1 - np.cos(k[3] * a))
    if m == 'tanh2':
        d += k[2] * np.tanh(k[3] * a)
    if m == 'rat':
        d += k[2] * a / (1 + k[3] * a * a)
    return d

def solve(x, y, m):
    from scipy.optimize import least_squares
    keep = fit(x, y, 'affine')[1]
    (x, y) = (x[keep], y[keep])
    w = np.ones(len(x))
    k = np.full(4, 1.5)
    for _ in range(5):

        def params(k):
            D = design(x, k, m)
            b = np.linalg.lstsq(D * w[:, None], y * w[:, None], rcond=None)[0]
            return (D, b)

        def fun(k):
            (D, b) = params(k)
            return ((D @ b - y) * w[:, None]).ravel()
        k = least_squares(fun, k, bounds=(0.35, 4), max_nfev=65).x
        (D, b) = params(k)
        r = np.linalg.norm(D @ b - y, axis=1)
        w = (1 + (r / max(0.004, 1.5 * np.median(r))) ** 2) ** (-0.25)
    return (k, b)
